Q: Full centering component A: <p>I have managed to find proper solution for what I want to do.
I have managed to make react-center component work properly and this is the code that is working:</p>

<pre><code>    import React from 'react';
import ReactCenter from 'react-center';
import {Row, Col} from 'react-flexbox-grid';
import Input from '@material-ui/core/Input';
import Button from '@material-ui/core/Button';


class Login extends React.Component{
    render(){
        return(
            &lt;div id="loginForm" style={{height: "100vh", width: "100vw"}}&gt;
                &lt;ReactCenter style={{height: "100vh", width: "100vw"}}&gt;
                        &lt;div style={{height: "200px", width: "300px"}}&gt;
                            &lt;Row&gt;
                                &lt;Col xs="3" sm="3" lg="3"/&gt;

                                &lt;Col xs="6" sm="6" lg="6"&gt;
                                    &lt;Input placeholder="username" /&gt;
                                &lt;/Col&gt;

                                &lt;Col xs="3" sm="3" lg="3"/&gt;
                            &lt;/Row&gt;

                            &lt;br/&gt;

                            {/*Row for password*/}
                            &lt;Row&gt;
                                &lt;Col xs="3" sm="3" lg="3"/&gt;

                                &lt;Col xs="6" sm="6" lg="6"&gt;
                                    &lt;Input placeholder="password" type="password" /&gt;
                                &lt;/Col&gt;

                                &lt;Col xs="3" sm="3" lg="3"/&gt;
                            &lt;/Row&gt;

                            &lt;br/&gt;

                            &lt;Row&gt;
                                &lt;Col xs="3" sm="3" lg="3"/&gt;

                                &lt;Col xs="6" sm="6" lg="6"&gt;
                                    &lt;Button variant="outlined" color="primary"&gt;Login&lt;/Button&gt;
                                &lt;/Col&gt;

                                &lt;Col xs="3" sm="3" lg="3"/&gt;
                            &lt;/Row&gt;
                        &lt;/div&gt;
                &lt;/ReactCenter&gt;
            &lt;/div&gt;
        );
    }
}

export default Login;
</code></pre>

<p>And ofc, I had to place  <strong>style="height: 100vh;"</strong> in the index.html for the main div.</p>

