Q: UI freezes in simple async computation A: <p>Perhaps the desired result can be achieved using <code>PauseToken</code>?</p>
<pre class="lang-dart prettyprint-override"><code>import 'dart:async';

import 'package:multitasking/misc/pause.dart';

void main(List&lt;String&gt; args) {
  final pts = PauseTokenSource();
  final token = pts.token;
  print('isPaused: ${token.isPaused}');
  _run(token);

  var count = 0;
  Timer.periodic(Duration(milliseconds: 300), (timer) {
    if (token.isPaused) {
      pts.resume();
    } else {
      pts.pause();
    }

    print('isPaused: ${token.isPaused}');
    if (count++ == 7) {
      timer.cancel();
    }
  });
}

Future&lt;void&gt; _run(PauseToken token) async {
  for (int i = 0; i &lt; 10; i++) {
    await Future&lt;void&gt;.delayed(const Duration(milliseconds: 100));
    await token.wait();
    setState(() =&gt; _text = '$i');
    print('Text: $_text');
  }
}

String _text = '';

void setState(void Function() f) {
  f();
}

</code></pre>
